1	import { useRef, useState, useEffect, useMemo } from 'react';
2	import { useNavigate, useParams } from 'react-router-dom';
3	import { useFights } from '../hooks/useFights';
4	import { useEvents } from '../hooks/useEvents';
5	import { useFighterFrames } from '../hooks/useFighterFrames';
6	import { useRounds } from '../hooks/useRounds';
7	import { useWindowWidth } from '../hooks/useWindowWidth';
8	import {
9	  createEvent, updateEvent, deleteEvent, finishLabeling, deleteFight,
10	  type CreateEventPayload,
11	} from '../services/api';
12	import type { SpanKind } from '../components/annotate/taxonomy';
13	import { isFightViewable, isLabelingReady, needsRoundReview, STATE_LABELS } from '../types/Fight';
14	import type { Event } from '../types/Event';
15	import { describeEvent } from '../utils/describeEvent';
16	import { isFrameSwapped } from '../utils/cornerSwap';
17	import ConfirmDialog from '../components/ConfirmDialog';
18	import VideoControls from '../components/VideoControls';
19	import FrameInfo from '../components/FrameInfo';
20	import type { FighterOverlayHandle } from '../components/FighterOverlay';
21	import AnnotateStage from '../components/annotate/AnnotateStage';
22	import FighterSelectCard from '../components/annotate/FighterSelectCard';
23	import EventPalette from '../components/annotate/EventPalette';
24	import FightEndModal, { type FightEndResult } from '../components/annotate/FightEndModal';
25	import KeyboardLegend from '../components/annotate/KeyboardLegend';
26	import AnnotationPanel from '../components/annotate/AnnotationPanel';
27	import SaveStatus from '../components/annotate/SaveStatus';
28	import FightPurposeBadge from '../components/FightPurposeBadge';
29	import { KEYMAP, colorForAction, iconForAction, successForAction, type Corner, type ToolItem } from '../components/annotate/taxonomy';
30	
31	export default function Annotate() {
32	  const { id } = useParams<{ id: string }>();
33	  const navigate = useNavigate();
34	  const fightId = id ? Number(id) : null;
35	
36	  const videoRef = useRef<HTMLVideoElement>(null);
37	  const overlayRef = useRef<FighterOverlayHandle>(null);
38	  const rafRef = useRef<number | null>(null);
39	  const fpsRef = useRef<number>(30);
40	  const lastFrameRef = useRef<number>(-1);
41	  const [isPlaying, setIsPlaying] = useState(false);
42	  const [currentTime, setCurrentTime] = useState(0);
43	  const [duration, setDuration] = useState(0);
44	
45	  const { fights } = useFights();
46	  const selectedFight = fights.find(f => f.id === fightId) ?? null;
47	  const { events: allEvents, setEvents: setAllEvents } = useEvents(fightId, { source: 'label' });
48	  const events = useMemo(() => allEvents.filter(e => e.kind === 'point'), [allEvents]);
49	  const spans = useMemo(() => allEvents.filter(e => e.kind !== 'point'), [allEvents]);
50	  const { frameMap } = useFighterFrames(fightId);
51	  const { rounds } = useRounds(fightId);
52	  const width = useWindowWidth();
53	  const narrow = width < 1100;
54	
55	  const fps = selectedFight?.fps ?? 30;
56	  fpsRef.current = fps;
57	
58	  const ready = selectedFight !== null && isLabelingReady(selectedFight.state);
59	
60	  useEffect(() => {
61	    const video = videoRef.current;
62	    if (!video || !ready) return;
63	    if (!isPlaying) {
64	      if (rafRef.current !== null) {
65	        video.cancelVideoFrameCallback(rafRef.current);
66	        rafRef.current = null;
67	      }
68	      return;
69	    }
70	    const tick = (_now: DOMHighResTimeStamp, metadata: VideoFrameCallbackMetadata) => {
71	      const frame = Math.floor(metadata.mediaTime * fpsRef.current) + 1;
72	      overlayRef.current?.draw(frame);
73	      if (frame !== lastFrameRef.current) {
74	        lastFrameRef.current = frame;
75	        setCurrentTime(metadata.mediaTime);
76	      }
77	      rafRef.current = video.requestVideoFrameCallback(tick);
78	    };
79	    rafRef.current = video.requestVideoFrameCallback(tick);
80	    return () => {
81	      if (rafRef.current !== null) {
82	        video.cancelVideoFrameCallback(rafRef.current);
83	        rafRef.current = null;
84	      }
85	    };
86	  }, [isPlaying, ready]);
87	
88	  const currentFrame = Math.floor(currentTime * fps) + 1;
89	  const currentMs = Math.floor(currentTime * 1000);
90	  const videoSrc = selectedFight ? `/fights/${selectedFight.id}/video` : undefined;
91	
92	  const togglePlay = () => {
93	    const video = videoRef.current;
94	    if (!video) return;
95	    if (isPlaying) video.pause(); else video.play();
96	    setIsPlaying(!isPlaying);
97	  };
98	
99	  const stepFrame = (delta: number) => {
100	    const video = videoRef.current;
101	    if (!video) return;
102	    video.pause();
103	    setIsPlaying(false);
104	    const newTime = Math.min(Math.max(video.currentTime + delta / fps, 0), video.duration);
105	    video.currentTime = newTime;
106	    setCurrentTime(newTime);
107	    overlayRef.current?.draw(Math.floor(newTime * fpsRef.current) + 1);
108	  };
109	
110	  const handleSeek = (time: number) => {
111	    const video = videoRef.current;
112	    if (!video) return;
113	    video.currentTime = time;
114	    setCurrentTime(time);
115	    overlayRef.current?.draw(Math.floor(time * fpsRef.current) + 1);
116	  };
117	
118	  const seekToFrame = (frame: number) => handleSeek(Math.max(0, (frame - 1) / fps));
119	
120	  const currentRound = rounds.find(r => currentFrame >= r.start_frame && currentFrame <= r.end_frame)?.round_number ?? '-';
121	
122	  const redName = selectedFight?.red_fighter_name ?? 'Red corner';
123	  const blueName = selectedFight?.blue_fighter_name ?? 'Blue corner';
124	
125	  // Reconstructs each point event's display text on the fly (description is
126	  // only ever stored for fight_end) — including the swap-corrected fighter
127	  // name for any event whose own frame falls inside a corner_swap span, so
128	  // reviewing the timeline reflects a swap the moment it's marked, even for
129	  // strikes logged before the span existed.
130	  const cornerSwapSpans = useMemo(
131	    () => spans.filter(s => s.kind === 'corner_swap').map(s => ({ frame: s.frame, end_frame: s.end_frame })),
132	    [spans],
133	  );
134	  const describe = (e: Event) => describeEvent(e, {
135	    redName, blueName, swapped: isFrameSwapped(e.frame, cornerSwapSpans),
136	  });
137	
138	  // ---- annotation logging state ----
139	  const [selected, setSelected] = useState<Corner | null>(null);
140	  const [toast, setToast] = useState<{ text: string; color: string; icon: string } | null>(null);
141	  const [flashId, setFlashId] = useState<number | null>(null);
142	  const [hint, setHint] = useState(false);
143	  const [endOpen, setEndOpen] = useState(false);
144	  const [savingCount, setSavingCount] = useState(0);
145	  const [finishing, setFinishing] = useState(false);
146	  const [confirmDelete, setConfirmDelete] = useState(false);
147	  const [deletingFight, setDeletingFight] = useState(false);
148	  const [deleteError, setDeleteError] = useState<string | null>(null);
149	  // Timeline clip selected by click — Delete removes it. Separate from
150	  // `flashId` (a transient highlight after creation) and from `selected`
151	  // (the red/blue corner for the *next* logged event).
152	  const [selectedEventId, setSelectedEventId] = useState<number | null>(null);
153	
154	  const frameRef = useRef(1);
155	  frameRef.current = currentFrame;
156	  const selRef = useRef<Corner | null>(null);
157	  selRef.current = selected;
158	  const endOpenRef = useRef(false);
159	  endOpenRef.current = endOpen;
160	  const confirmDeleteRef = useRef(false);
161	  confirmDeleteRef.current = confirmDelete;
162	  const selectedEventIdRef = useRef<number | null>(null);
163	  selectedEventIdRef.current = selectedEventId;
164	  const sessionIdsRef = useRef<number[]>([]);
165	
166	  const toastTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
167	  const hintTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
168	  const flashTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
169	
170	  const showToast = (text: string, color: string, icon: string) => {
171	    setToast({ text, color, icon });
172	    clearTimeout(toastTimer.current);
173	    toastTimer.current = setTimeout(() => setToast(null), 1100);
174	  };
175	
176	  const flash = (eventId: number) => {
177	    setFlashId(eventId);
178	    clearTimeout(flashTimer.current);
179	    flashTimer.current = setTimeout(() => setFlashId(null), 700);
180	  };
181	
182	  const addEvent = async (payload: CreateEventPayload) => {
183	    if (!fightId) return null;
184	    setSavingCount(c => c + 1);
185	    try {
186	      const created = await createEvent(fightId, { kind: 'point', ...payload });
187	      setAllEvents(prev => [...prev, created]);
188	      sessionIdsRef.current.push(created.id);
189	      flash(created.id);
190	      return created;
191	    } catch {
192	      showToast('Failed to save event', 'var(--f-red)', 'error');
193	      return null;
194	    } finally {
195	      setSavingCount(c => c - 1);
196	    }
197	  };
198	
199	  const removeEvent = async (eventId: number) => {
200	    if (!fightId) return;
201	    setSavingCount(c => c + 1);
202	    try {
203	      await deleteEvent(fightId, eventId);
204	      setAllEvents(prev => prev.filter(e => e.id !== eventId));
205	      sessionIdsRef.current = sessionIdsRef.current.filter(x => x !== eventId);
206	      if (selectedEventIdRef.current === eventId) setSelectedEventId(null);
207	    } catch {
208	      showToast('Failed to delete event', 'var(--f-red)', 'error');
209	    } finally {
210	      setSavingCount(c => c - 1);
211	    }
212	  };
213	
214	  // corner_swap / excluded are start/end toggles: one key opens a span at the
215	  // playhead, the next press of the same key closes it. `openSpanRef` tracks
216	  // the in-flight span id per kind so the second press knows what to close.
217	  const openSpanRef = useRef<Partial<Record<SpanKind, number>>>({});
218	  const SPAN_LABEL: Record<SpanKind, string> = { round: 'Round', corner_swap: 'Corner swap', excluded: 'Excluded' };
219	
220	  const toggleSpan = async (kind: SpanKind) => {
221	    if (!fightId) return;
222	    const openId = openSpanRef.current[kind];
223	    const frame = frameRef.current;
224	    if (openId != null) {
225	      try {
226	        const start = spans.find(s => s.id === openId)?.frame ?? frame;
227	        const patch = frame < start ? { frame, end_frame: start } : { end_frame: frame };
228	        const updated = await updateEvent(fightId, openId, patch);
229	        setAllEvents(prev => prev.map(s => (s.id === openId ? updated : s)));
230	        showToast(`${SPAN_LABEL[kind]} span closed`, 'var(--slate-400)', 'flag');
231	      } catch {
232	        showToast('Failed to close span', 'var(--f-red)', 'error');
233	      } finally {
234	        delete openSpanRef.current[kind];
235	      }
236	      return;
237	    }
238	    try {
239	      const created = await createEvent(fightId, {
240	        kind, frame, value: kind === 'excluded' ? 'replay' : null,
241	      });
242	      setAllEvents(prev => [...prev, created]);
243	      openSpanRef.current[kind] = created.id;
244	      showToast(`${SPAN_LABEL[kind]} span opened`, 'var(--slate-400)', 'flag');
245	    } catch {
246	      showToast('Failed to open span', 'var(--f-red)', 'error');
247	    }
248	  };
249	
250	  const updateSpan = async (spanId: number, patch: { frame?: number; end_frame?: number }) => {
251	    if (!fightId) return;
252	    try {
253	      const updated = await updateEvent(fightId, spanId, patch);
254	      setAllEvents(prev => prev.map(s => (s.id === spanId ? updated : s)));
255	    } catch {
256	      showToast('Failed to update span', 'var(--f-red)', 'error');
257	    }
258	  };
259	
260	  const removeSpan = async (spanId: number) => {
261	    if (!fightId) return;
262	    try {
263	      await deleteEvent(fightId, spanId);
264	      setAllEvents(prev => prev.filter(s => s.id !== spanId));
265	      for (const [kind, id] of Object.entries(openSpanRef.current)) {
266	        if (id === spanId) delete openSpanRef.current[kind as SpanKind];
267	      }
268	    } catch {
269	      showToast('Failed to delete span', 'var(--f-red)', 'error');
270	    }
271	  };
272	
273	  const undo = () => {
274	    const lastId = sessionIdsRef.current[sessionIdsRef.current.length - 1];
275	    if (lastId == null) return;
276	    removeEvent(lastId);
277	  };
278	
279	  const logTool = (item: ToolItem, shiftKey = false) => {
280	    if (!selectedFight) return;
281	    const corner = selRef.current;
282	    if (item.needsFighter && !corner) {
283	      setHint(true);
284	      clearTimeout(hintTimer.current);
285	      hintTimer.current = setTimeout(() => setHint(false), 1100);
286	      showToast('Select a fighter first', 'var(--f-red)', 'error');
287	      return;
288	    }
289	    // Fighter-independent tools (fight state) must not pick up whichever corner
290	    // happens to be selected — neither in the stored corner nor in the toast.
291	    const cornerIdx = item.needsFighter ? (corner === 'red' ? 0 : 1) : null;
292	    const fighterName = item.needsFighter ? (corner === 'red' ? redName : blueName) : '';
293	    const target = item.hasTarget ? (shiftKey ? 'body' : 'head') : item.fixedTarget ?? null;
294	    // `description` is only kept as a local for the toast text below — it's
295	    // no longer sent to the backend. Every action here except fight_end is
296	    // fully reconstructable from action/target/corner (see describeEvent.ts),
297	    // so storing a frozen copy would only go stale the next time a
298	    // corner_swap span is added or edited.
299	    const description = item.text(fighterName, target ?? undefined);
300	    const color = colorForAction(item.action);
301	    const icon = iconForAction(item.action);
302	    addEvent({
303	      frame: frameRef.current,
304	      corner: cornerIdx,
305	      action: item.action,
306	      target,
307	      success: successForAction(item.action),
308	    }).then(created => {
309	      if (!created) return;
310	      if (!item.needsFighter) { showToast(description, color, icon); return; }
311	      const targetSuffix = item.hasTarget ? ` · ${target === 'body' ? 'Body' : 'Head'}` : '';
312	      showToast(`${item.name} · ${fighterName}${targetSuffix}`, color, icon);
313	    });
314	  };
315	
316	  const confirmFightEnd = (result: FightEndResult) => {
317	    const winnerCorner = result.winner === 'red' ? 0 : result.winner === 'blue' ? 1 : null;
318	    const winnerName = result.winner === 'red' ? redName : result.winner === 'blue' ? blueName : null;
319	    const outcome = result.method === 'Draw' || !winnerName
320	      ? 'Draw'
321	      : result.method === 'Decision' ? `${winnerName} by decision` : `${winnerName} by ${result.method}`;
322	    const description = `Fight ended — ${outcome}${result.detail ? ' (' + result.detail + ')' : ''}`;
323	    const endFrame = frameRef.current;
324	    addEvent({
325	      frame: endFrame,
326	      description,
327	      corner: winnerCorner,
328	      action: 'fight_end',
329	      success: null,
330	    }).then(created => {
331	      if (!created) return;
332	      showToast(`Fight ended · ${result.method}`, 'var(--purple-600)', 'sports_score');
333	
334	      // The round span was seeded from the AI's scheduled-length guess,
335	      // which now runs past the real end of the fight — auto-exclude the
336	      // tail so it isn't scored/trained on as if it were live action.
337	      // Visible and editable in the timeline like any other excluded span,
338	      // not a silent adjustment (TODO.md #4).
339	      if (!fightId) return;
340	      const containingRound = spans.find(
341	        s => s.kind === 'round' && s.frame <= endFrame &&
342	             (s.end_frame == null || endFrame <= s.end_frame),
343	      );
344	      if (containingRound?.end_frame != null && containingRound.end_frame > endFrame) {
345	        createEvent(fightId, {
346	          kind: 'excluded',
347	          frame: endFrame + 1,
348	          end_frame: containingRound.end_frame,
349	          value: 'post fight_end',
350	        }).then(span => setAllEvents(prev => [...prev, span]));
351	      }
352	    });
353	    setEndOpen(false);
354	  };
355	
356	  const handleFinishLabeling = async () => {
357	    if (!fightId) return;
358	    setFinishing(true);
359	    try {
360	      await finishLabeling(fightId);
361	      navigate(`/fights/${fightId}`);
362	    } catch (err) {
363	      showToast(err instanceof Error ? err.message : 'Failed to finish labeling', 'var(--f-red)', 'error');
364	      setFinishing(false);
365	    }
366	  };
367	
368	  const handleDeleteFight = async () => {
369	    if (!fightId) return;
370	    setDeletingFight(true);
371	    setDeleteError(null);
372	    try {
373	      // The DELETE unlinks the file this <video> is streaming — stop playback
374	      // (and the requestVideoFrameCallback loop) before pulling it out from under us.
375	      videoRef.current?.pause();
376	      setIsPlaying(false);
377	      await deleteFight(fightId);
378	      // replace: Back must not return to a now-dead /fights/{id}/annotate.
379	      navigate('/', { replace: true });
380	    } catch (err) {
381	      setDeleteError(err instanceof Error ? err.message : 'Failed to delete fight');
382	      setDeletingFight(false);
383	    }
384	  };
385	
386	  // stable "latest callback" ref so the global keydown listener (registered once)
387	  // always calls the current render's closures, without re-registering constantly
388	  const fnsRef = useRef({ togglePlay, stepFrame, logTool, undo, setSelected, toggleSpan, removeEvent });
389	  fnsRef.current = { togglePlay, stepFrame, logTool, undo, setSelected, toggleSpan, removeEvent };
390	
391	  useEffect(() => {
392	    if (!ready) return;
393	    const onKey = (e: KeyboardEvent) => {
394	      if (e.metaKey || e.ctrlKey || e.altKey) return;
395	      const target = e.target as HTMLElement;
396	      const tag = target.tagName;
397	      if (tag === 'INPUT' || tag === 'TEXTAREA' || target.isContentEditable) return;
398	      // Any modal swallows every shortcut — otherwise z/o/p/digits keep logging
399	      // label events behind the overlay, and Escape would double-fire.
400	      if (endOpenRef.current || confirmDeleteRef.current) return;
401	
402	      const fns = fnsRef.current;
403	      const k = e.key;
404	      const time = (frameRef.current - 1) / fpsRef.current;
405	
406	      if (k === ' ') { e.preventDefault(); fns.togglePlay(); return; }
407	      if (k === 'ArrowLeft') { e.preventDefault(); handleSeek(Math.max(0, time - (e.shiftKey ? 5 : 1))); return; }
408	      if (k === 'ArrowRight') { e.preventDefault(); handleSeek(time + (e.shiftKey ? 5 : 1)); return; }
409	      if (k === ',') { e.preventDefault(); fns.stepFrame(-1); return; }
410	      if (k === '.') { e.preventDefault(); fns.stepFrame(1); return; }
411	      if (k === 'Escape') { fns.setSelected(null); setSelectedEventId(null); return; }
412	
413	      const lk = k.length === 1 ? k.toLowerCase() : k;
414	      if (lk === 'r') { fns.setSelected('red'); return; }
415	      if (lk === 'b') { fns.setSelected('blue'); return; }
416	      // Backspace/Delete: delete the selected timeline clip if one is
417	      // selected, else undo the last event logged this session. On Mac the
418	      // one physical "delete" key sends Backspace (e.key === 'Delete' is
