423	        if (selectedEventIdRef.current != null) fns.removeEvent(selectedEventIdRef.current);
424	        else fns.undo();
425	        return;
426	      }
427	      if (lk === 'z') { e.preventDefault(); fns.undo(); return; }
428	      if (lk === 'o') { e.preventDefault(); fns.toggleSpan('corner_swap'); return; }
429	      if (lk === 'p') { e.preventDefault(); fns.toggleSpan('excluded'); return; }
430	
431	      // Digit keys need e.code, not e.key: Shift+1 types '!' on a US layout,
432	      // so reading e.key would break the KEYMAP lookup for the target modifier.
433	      const toolKey = e.code.startsWith('Digit') ? e.code.slice(5) : lk;
434	      const tool = KEYMAP[toolKey];
435	      if (tool) { e.preventDefault(); fns.logTool(tool, e.shiftKey); }
436	    };
437	    window.addEventListener('keydown', onKey);
438	    return () => window.removeEventListener('keydown', onKey);
439	  }, [ready]);
440	
441	  // ---- guard states ----
442	  if (selectedFight === null) {
443	    return (
444	      <div style={{ display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center', minHeight: 'calc(100vh - 58px)', padding: 24 }}>
445	        <span className="material-symbols-outlined" style={{ fontSize: 32, color: '#64748b', animation: 'spin 1.5s linear infinite' }}>progress_activity</span>
446	      </div>
447	    );
448	  }
449	
450	  if (isFightViewable(selectedFight.state)) {
451	    return (
452	      <div style={{ display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center', minHeight: 'calc(100vh - 58px)', padding: 24 }}>
453	        <div style={{
454	          textAlign: 'center', background: 'rgba(255,255,255,0.04)', backdropFilter: 'blur(24px) saturate(160%)',
455	          border: '1px solid rgba(255,255,255,0.07)', borderRadius: 20, padding: '48px 56px', maxWidth: 420,
456	        }}>
457	          <span className="material-symbols-outlined" style={{ fontSize: 40, color: 'var(--accent)', display: 'block', marginBottom: 16 }}>check_circle</span>
458	          <h2 style={{ fontSize: 20, fontWeight: 800, margin: '0 0 10px', color: '#f1f5f9' }}>This fight is already labeled</h2>
459	          <p style={{ fontSize: 14, color: '#475569', margin: '0 0 20px', lineHeight: 1.6 }}>Open it in the Player to review the tagged events.</p>
460	          <button onClick={() => navigate(`/fights/${selectedFight.id}`)} className="btn-glass" style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '8px 16px', fontSize: 13, fontWeight: 600, borderRadius: 8 }}>
461	            <span className="material-symbols-outlined" style={{ fontSize: 16 }}>play_circle</span>
462	            Open Player
463	          </button>
464	        </div>
465	      </div>
466	    );
467	  }
468	
469	  if (!ready) {
470	    return (
471	      <div style={{ display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center', minHeight: 'calc(100vh - 58px)', padding: 24 }}>
472	        <div style={{
473	          textAlign: 'center', background: 'rgba(255,255,255,0.04)', backdropFilter: 'blur(24px) saturate(160%)',
474	          border: '1px solid rgba(255,255,255,0.07)', borderRadius: 20, padding: '48px 56px', maxWidth: 420,
475	        }}>
476	          <span className="material-symbols-outlined" style={{ fontSize: 40, color: '#64748b', display: 'block', marginBottom: 16, animation: 'spin 1.5s linear infinite' }}>progress_activity</span>
477	          <h2 style={{ fontSize: 20, fontWeight: 800, margin: '0 0 10px', color: '#f1f5f9' }}>
478	            {STATE_LABELS[selectedFight.state] ?? 'Detecting fighters'}
479	          </h2>
480	          <p style={{ fontSize: 14, color: '#475569', margin: '0 0 20px', lineHeight: 1.6 }}>
481	            Fighters are still being detected — labeling opens once that's done.
482	          </p>
483	          <button onClick={() => navigate('/')} className="btn-glass" style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '8px 16px', fontSize: 13, fontWeight: 600, borderRadius: 8 }}>
484	            <span className="material-symbols-outlined" style={{ fontSize: 16 }}>arrow_back</span>
485	            Back to fights
486	          </button>
487	        </div>
488	      </div>
489	    );
490	  }
491	
492	  return (
493	    <div style={{ position: 'relative', zIndex: 1, width: '100%', boxSizing: 'border-box', maxWidth: 1560, margin: '0 auto', padding: narrow ? '16px 14px 48px' : '22px 30px 70px' }}>
494	      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 16 }}>
495	        <button onClick={() => navigate('/')} className="icon-btn" style={{ width: 38, height: 38 }}>
496	          <span className="material-symbols-outlined" style={{ fontSize: 20 }}>arrow_back</span>
497	        </button>
