510	            color: '#001f24', fontWeight: 700, fontSize: 13, border: 'none', borderRadius: 10, padding: '9px 16px',
511	            cursor: finishing ? 'not-allowed' : 'pointer', opacity: finishing ? 0.5 : 1,
512	            boxShadow: finishing ? 'none' : '0 0 16px rgba(0,218,243,0.25)', fontFamily: 'inherit',
513	          }}
514	        >
515	          <span className="material-symbols-outlined" style={{ fontSize: 18 }}>{finishing ? 'progress_activity' : 'task_alt'}</span>
516	          Finish Labeling
517	        </button>
518	        <button
519	          onClick={() => { setDeleteError(null); setConfirmDelete(true); }}
520	          title="Delete this fight"
521	          style={{
522	            width: 38, height: 38, flexShrink: 0, display: 'grid', placeItems: 'center',
523	            borderRadius: 10, border: '1px solid rgba(239,68,68,0.25)',
524	            background: 'rgba(239,68,68,0.08)', color: '#ef4444',
525	            cursor: 'pointer', fontFamily: 'inherit',
526	          }}
527	        >
528	          <span className="material-symbols-outlined" style={{ fontSize: 20 }}>delete</span>
529	        </button>
530	      </div>
531	
532	      <ConfirmDialog
533	        open={confirmDelete}
534	        title="DELETE FIGHT?"
535	        message={
536	          <>
537	            <strong style={{ color: 'var(--text-primary)' }}>{redName} vs {blueName}</strong> will be
538	            permanently deleted — the source video file, every hand label and span you have annotated
539	            so far, plus all pipeline predictions, rounds and tracked fighter frames. This cannot be undone.
540	          </>
541	        }
542	        confirmLabel="Delete fight"
543	        confirmIcon="delete_forever"
